<?php
declare(strict_types=1);
require __DIR__.'/bootstrap.php';if(empty($_SESSION['admin_id']))redirect('index.php');require_once dirname(__DIR__).'/private/routing_store.php';
$day=(string)($_GET['date']??date('Y-m-d'));if(!zgsValidDate($day))$day=date('Y-m-d');$back='route.php?date='.$day;$error=$_SESSION['route_error']??'';unset($_SESSION['route_error']);
if($_SERVER['REQUEST_METHOD']==='POST'){checkCsrf();try{$action=(string)($_POST['action']??'');
 if($action==='settings'){$start=trim((string)($_POST['start_address']??''));$end=trim((string)($_POST['end_address']??''));if(mb_strlen($start)>255||mb_strlen($end)>255)throw new InvalidArgumentException('Adresse maximal 255 Zeichen.');$pdo->prepare('UPDATE planning_settings SET route_start_address=?,route_end_address=? WHERE id=1')->execute([$start,$end]);}
 elseif($action==='location'){$address=trim((string)($_POST['address']??''));$source=trim((string)($_POST['source']??''));$lat=filter_var($_POST['latitude']??'',FILTER_VALIDATE_FLOAT);$lon=filter_var($_POST['longitude']??'',FILTER_VALIDATE_FLOAT);if(empty($_POST['checked'])||$address===''||mb_strlen($address)>255||$source===''||mb_strlen($source)>190||$lat===false||$lon===false||$lat< -90||$lat>90||$lon< -180||$lon>180)throw new InvalidArgumentException('Adresse, Quelle, geprüfte Koordinaten und ausdrückliche Bestätigung erforderlich.');$key=hash('sha256',$address);$pdo->prepare("INSERT INTO routing_locations(location_key,address,latitude,longitude,source,quality,checked_at) VALUES(?,?,?,?,?,'manuell_geprueft',NOW()) ON DUPLICATE KEY UPDATE latitude=VALUES(latitude),longitude=VALUES(longitude),source=VALUES(source),quality=VALUES(quality),checked_at=NOW()")->execute([$key,$address,$lat,$lon,$source]);}
 elseif($action==='preview'){$provider=null;if(filter_var($config['routing_enabled']??false,FILTER_VALIDATE_BOOLEAN)&&!empty($config['routing_osrm_endpoint']))$provider=new GszOsrmProvider($config['routing_osrm_endpoint']);$token=routeSaveProposal($pdo,(int)$_SESSION['admin_id'],$day,$provider,(int)($config['routing_cache_ttl']??3600),(int)($config['routing_max_points']??25));redirect($back.'&proposal='.$token);}
 elseif($action==='apply'){if(empty($_POST['confirm']))throw new RuntimeException('Übernahme ausdrücklich bestätigen.');routeApply($pdo,(int)$_SESSION['admin_id'],(string)($_POST['token']??''));redirect($back.'&proposal='.rawurlencode((string)$_POST['token']));}
 else throw new InvalidArgumentException('Unbekannte Aktion.');
 }catch(Throwable $e){$_SESSION['route_error']=$e instanceof PDOException?'Route nicht verfügbar. Migration prüfen.':$e->getMessage();}redirect($back);}
$settings=null;$proposal=null;$locations=[];try{$settings=routeSettings($pdo);$locations=$pdo->query('SELECT * FROM routing_locations ORDER BY address LIMIT 500')->fetchAll();if(isset($_GET['proposal'])){$q=$pdo->prepare('SELECT * FROM planning_proposals WHERE token=? AND admin_id=?');$q->execute([(string)$_GET['proposal'],$_SESSION['admin_id']]);$proposal=$q->fetch();if($proposal&&((json_decode($proposal['payload'],true)['kind']??'')!=='route'))$proposal=null;}}catch(Throwable $e){$error='Route benötigt die Phase-3-Migration.';}
function routeHidden(string $action):void{echo '<input type="hidden" name="csrf" value="'.e(csrf()).'"><input type="hidden" name="action" value="'.e($action).'">';}
?><!doctype html><html lang="de"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Route optimieren · GSZ</title><link rel="stylesheet" href="zentrale.css"></head><body><main><header><a href="planner.php?date=<?=e($day)?>">← Tagesplan</a><a href="waste.php">Müllkalender</a></header><h1>Route optimieren</h1><p>Nachvollziehbare Tourenheuristik, kein mathematisch optimales Ergebnis. Keine Standortverfolgung. Navigation nur durch Klick. Bedienung bitte im Stand.</p><?php if($error):?><p class="error" role="alert"><?=e($error)?></p><?php endif?><form method="get"><label>Routentag<input type="date" name="date" value="<?=e($day)?>"></label><button>Tag öffnen</button></form>
<?php if($settings):?><section class="card"><h2>Start und Ziel</h2><p>Startzeit aus Tagesplanung, standardmäßig 10:30. Keine Uni-/Privatadresse vorgegeben.</p><form method="post"><?php routeHidden('settings');?><label>Tatsächlicher Start nach Uni oder Zuhause<input name="start_address" maxlength="255" value="<?=e($settings['route_start_address'])?>" placeholder="Erst tatsächliche Adresse eintragen"></label><label>Tatsächliches Endziel Zuhause oder Fitnessstudio<input name="end_address" maxlength="255" value="<?=e($settings['route_end_address'])?>"></label><button>Start/Ziel speichern</button></form></section><form method="post"><?php routeHidden('preview');?><button>Route als Vorschau berechnen</button></form><p>Provider <?=filter_var($config['routing_enabled']??false,FILTER_VALIDATE_BOOLEAN)?'serverseitig aktiviert; Nutzung nur bei ausdrücklicher Vorschauanfrage':'deaktiviert – vollständig offline'?>. Keine Anfrage beim bloßen Öffnen. Schätzpuffer: <?=(int)$settings['buffer_minutes']?> Min. je Objektwechsel; bei 0 keine Fahrzeitreserve. Fixtermin-Anfahrt ohne Routingdaten unsicher.</p>
<?php if($proposal):$p=json_decode($proposal['payload'],true,512,JSON_THROW_ON_ERROR);$r=$p['route'];?><section class="card"><h2><?=$proposal['applied_at']?'Bestätigte Route (gespeicherter Stand)':'Routenvorschau – noch nicht übernommen'?></h2><p><?=e($r['mode'])?><?php if($r['source']):?> · Quelle <?=e($r['source'])?> · Stand <?=e($r['timestamp'])?> · <?=number_format($r['meters']/1000,2,',','.')?> km · <?=number_format($r['seconds']/60,1,',','.')?> Min. Routingdauer<?php endif?></p><p>Arbeitsminuten <?=$r['timeline']['minutes']?> · berechnetes Ende <?=e(planTime($r['timeline']['end']))?> (bei unbekannter Dauer unvollständig)</p><?php foreach(array_merge($r['warnings'],$r['timeline']['warnings']) as $w):?><p class="error"><?=e($w)?></p><?php endforeach?>
<h3>Fahrabschnitte</h3><?php foreach($r['legs'] as $leg):?><p><?=e($leg['from']?:'Start unbekannt')?> → <?=e($leg['to']?:'Adresse unbekannt')?> · <?=$leg['seconds']===null?'Keine Routingdaten; Schätzpuffer '.(int)$leg['estimated_minutes'].' Min.':number_format($leg['meters']/1000,2,',','.').' km / '.number_format($leg['seconds']/60,1,',','.').' Min.'?></p><?php if($leg['to']):?><a target="_blank" rel="noopener noreferrer" href="https://www.google.com/maps/search/?api=1&amp;query=<?=e(rawurlencode($leg['to']))?>">Navigation zu diesem Ziel öffnen</a><?php endif?><?php endforeach?>
<h3>Aufgabenfolge / Änderungen</h3><?php foreach($r['timeline']['rows'] as $i=>$row):$t=$row['task'];?><article class="task-row"><strong><?=e($row['start']===null?'offen':planTime($row['start']))?>–<?=e($row['end']===null?'Dauer unbekannt':planTime($row['end']))?> <?=e($t['title'])?></strong><p><?=e($t['property_name']??'Ohne Objekt')?> · bisher Reihenfolge <?=(int)($t['planned_order']?:$t['sort_order'])?> → Vorschlag <?=$i+1?> · <?=planFixed($t)?'geschützt, unverändert':'flexible Reihenfolge'?></p><?php foreach($row['warnings'] as $w):?><p class="error"><?=e($w)?></p><?php endforeach?></article><?php endforeach?><?php if(!$proposal['applied_at']):?><form method="post"><?php routeHidden('apply');?><input type="hidden" name="token" value="<?=e($proposal['token'])?>"><label><input type="checkbox" name="confirm" required> Änderungen und offene Konflikte geprüft, nur flexible Reihenfolge übernehmen.</label><button>Route bestätigen und übernehmen</button></form><?php endif?></section><?php endif?>
<details class="card"><summary>Geprüfte Adressen / Koordinaten und manuelle Korrektur</summary><p>Keine automatische Geokodierung. Nur bewusst aus verlässlicher Quelle geprüfte Koordinaten eingeben; Qualitätsfreigabe gilt 90 Tage. Quellen- und Datenübermittlungsbedingungen vor Provideraktivierung prüfen.</p><?php foreach($locations as $l):?><p><?=e($l['address'])?> · <?=e($l['latitude'].', '.$l['longitude'])?> · <?=e($l['source'].' · '.$l['quality'].' · '.$l['checked_at'])?></p><?php endforeach?><form method="post"><?php routeHidden('location');?><label>Genaue gespeicherte Adresse<input name="address" maxlength="255" required></label><label>Breitengrad<input name="latitude" inputmode="decimal" required></label><label>Längengrad<input name="longitude" inputmode="decimal" required></label><label>Quelle<input name="source" maxlength="190" required></label><label><input type="checkbox" name="checked" required> Adresse und Koordinaten manuell geprüft.</label><button>Geprüfte Koordinaten speichern / korrigieren</button></form></details><?php endif?></main></body></html>
